import{_ as l,a0 as d,w as a,s as u,ao as p,I as i,x as e,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在筆記本電腦合蓋時不掛起 Ubuntu | LCTT x X-CMD","titleTemplate":false,"description":"如何在筆記本電腦合蓋時不掛起 Ubuntu | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在筆記本電腦合蓋時不掛起 Ubuntu | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在筆記本電腦合蓋時不掛起 Ubuntu | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220831 Don-t Suspend Ubuntu When Laptop Lid is Closed","title":"如何在筆記本電腦合蓋時不掛起 Ubuntu","tag":"202209","desc":""},"relativePath":"202209/20220831 Don-t Suspend Ubuntu When Laptop Lid is Closed.md","filePath":"[post].md"}'),r={name:"202209/20220831 Don-t Suspend Ubuntu When Laptop Lid is Closed.md"};function b(m,t,f,g,h,T){const s=d("Link");return a(),u("div",null,[t[18]||(t[18]=p('<h1 id="如何在筆記本電腦合蓋時不掛起-ubuntu" tabindex="-1">如何在筆記本電腦合蓋時不掛起 Ubuntu <a class="header-anchor" href="#如何在筆記本電腦合蓋時不掛起-ubuntu" aria-label="Permalink to “如何在筆記本電腦合蓋時不掛起 Ubuntu”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202209/09/230733ppyyws84ccgrc777.jpg" alt=""></p><p>如果你在筆記本電腦上使用 Ubuntu，你可能已經注意到當你合上蓋子時系統處於掛起狀態。</p><p>這是預期的行為。它可以節省電池和你的工作。你掀開蓋子，系統喚醒，你可以登錄並繼續工作。</p><p>這一切聽起來都不錯，除非你使用多顯示器設置。像我這樣的一些人更喜歡關閉筆記本電腦，只使用外接顯示器。</p><p>但是，如果關閉筆記本電腦蓋會掛起系統，那麼會產生問題。</p><p>讓我告訴你如何改變這種行為。</p><h3 id="關閉筆記本電腦蓋時不要掛起" tabindex="-1">關閉筆記本電腦蓋時不要掛起 <a class="header-anchor" href="#關閉筆記本電腦蓋時不要掛起" aria-label="Permalink to “關閉筆記本電腦蓋時不要掛起”">​</a></h3><p>實際上，我注意到最近的 Ubuntu 版本在這個情況下更智能。當筆記本電腦連接到擴展塢併合上蓋子時，它不會進入掛起模式。</p><p>這是正常的預期行為，但由於 Ubuntu 某種神才知道的原因，它可能不會一直有效。</p><p>好消息是你可以使用 GUI 和命令列強制更改此行為。</p><p>讓我分享這兩種方法。</p><h4 id="方法-1-使用-gnome-優化" tabindex="-1">方法 1：使用 GNOME 優化 <a class="header-anchor" href="#方法-1-使用-gnome-優化" aria-label="Permalink to “方法 1：使用 GNOME 優化”">​</a></h4>',13)),i("p",null,[t[1]||(t[1]=e("如果你使用的是默認的 GNOME 桌面，那麼你很幸運。 ",-1)),o(s,{href:"https://itsfoss.com/gnome-tweak-tool/"},{default:n(()=>[...t[0]||(t[0]=[e("在 Ubuntu 的軟件中心安裝 GNOME 優化（Tweaks）工具",-1)])]),_:1}),t[2]||(t[2]=e("，或使用以下命令：",-1))]),t[19]||(t[19]=p('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gnome-tweaks</span></span></code></pre></div><p>安裝後，啓動優化應用。在側邊欄的<ruby>常規<rt>General</rt></ruby>選項卡中，關閉“<ruby>筆記本電腦蓋合上時掛起<rt>Suspend when laptop lid is closed</rt></ruby>”按鈕。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/change-lid-close-behavior-ubuntu.png" alt="change lid close behavior ubuntu"></p><p>這就好了。你不需要重啓即可使更改生效。</p><p>現在，讓我們談談命令列方法。</p><h4 id="方法-2-更改登錄配置-針對高級用户" tabindex="-1">方法 2：更改登錄配置（針對高級用户） <a class="header-anchor" href="#方法-2-更改登錄配置-針對高級用户" aria-label="Permalink to “方法 2：更改登錄配置（針對高級用户）”">​</a></h4><p>如果你查看文件 <code>/etc/systemd/logind.conf</code> 的內容，你將看到三種不同類型的筆記本電腦合蓋默認設置：</p><ul><li><code>HandleLidSwitch=suspend</code>：當筆記本電腦使用電池供電時，合蓋掛起</li><li><code>HandleLidSwitchExternalPower=suspend</code>：當筆記本電腦插入電源插座時，合蓋掛起</li><li><code>HandleLidSwitchDocked=ignore</code>：當筆記本電腦連接到擴展塢時，合蓋忽略</li></ul><p><img src="https://itsfoss.com/wp-content/uploads/2022/08/laptop-lid-settings-ubuntu.png" alt="Default laptop lid closing settings"></p><p>如你所見，如果合上蓋子，筆記本電腦將掛起，無論它是否連接到電源。而連接擴展塢忽略合蓋。</p><p>如果需要，你可以根據自己的喜好將這些參數的值更改為其中之一：</p><ul><li><code>suspend</code>：合蓋時掛起</li><li><code>lock</code>：合蓋時鎖定</li><li><code>ignore</code>：什麼都不做</li><li><code>poweroff</code>：關機</li><li><code>hibernate</code>：合蓋時休眠</li></ul><p>如果你不希望你的系統在筆記本電腦蓋合上時執行任何特殊操作，我建議你使用 <code>ignore</code>。</p><p>你可以編輯 <code>/etc/systemd/logind.conf</code> 文件，或者在 <code>/etc/systemd/logind.conf.d</code> 目錄中創建一個新文件，並取消註釋上述設置並更改其值。如果此目錄不存在，請創建此目錄。</p><p>我不會給你確切的命令。如果你熟悉命令列，你應該可以做到。如果你對命令列感到不習慣，請使用前面的 GUI 方法。</p><p>我希望這可以幫助你。如果你有任何問題，請告訴我。</p><hr>',17)),i("p",null,[t[4]||(t[4]=e("via: ",-1)),o(s,{href:"https://itsfoss.com/laptop-lid-suspend-ubuntu/"},{default:n(()=>[...t[3]||(t[3]=[e("https://itsfoss.com/laptop-lid-suspend-ubuntu/",-1)])]),_:1})]),i("p",null,[t[9]||(t[9]=e("作者：",-1)),o(s,{href:"https://itsfoss.com/"},{default:n(()=>[...t[5]||(t[5]=[e("Abhishek Prakash",-1)])]),_:1}),t[10]||(t[10]=e(" 選題：",-1)),o(s,{href:"https://github.com/lkxed"},{default:n(()=>[...t[6]||(t[6]=[e("lkxed",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:n(()=>[...t[7]||(t[7]=[e("geekpi",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const x=l(r,[["render",b]]);export{C as __pageData,x as default};
